-- Department heads and reporting lines (heads report to the MD)
update public.departments d set head_id = e.id
from public.employees e
where (d.code, e.employee_no) in (('MGT','E001'), ('HR','E002'), ('FIN','E004'), ('OPS','E006'), ('SAL','E010'));

update public.employees e set manager_id = m.id
from public.employees m
where (e.employee_no, m.employee_no) in (
  ('E002','E001'), ('E004','E001'), ('E006','E001'), ('E010','E001'),
  ('E003','E002'), ('E005','E004'),
  ('E007','E006'), ('E008','E006'), ('E009','E006'),
  ('E011','E010'), ('E012','E010'));

-- ---------- Entitlements (pro-rated for 2026 joiners) ----------
select public._generate_entitlements(2026, null);
select public._generate_entitlements(2027, null);

-- ---------- Sign-ins for every employee ----------
do $$
declare
  v_hr uuid := (select id from public.employees where employee_no = 'E002');
  e record;
begin
  for e in select id from public.employees order by employee_no loop
    perform public._hr_create_login(v_hr, e.id, 'Workpath2026!');
  end loop;
end $$;

-- ---------- Sample workflow runs ----------
do $$
declare
  emp jsonb := (select jsonb_object_agg(employee_no, id) from public.employees);
  r jsonb;
begin
  -- Daniel: 4 days AL approved by Marcus  -> AL balance 10 / 14
  r := public._submit_leave((emp->>'E007')::uuid, 'AL', '2026-12-21', '2026-12-24', 'none', 'Year-end family trip', null);
  perform public._decide_leave((emp->>'E006')::uuid, (r->>'id')::uuid, 'approve', 'Enjoy the break');

  -- Ahmad: 2 days sick leave with MC, approved -> SL 12 / 14 (and counts toward HL cap)
  r := public._submit_leave((emp->>'E008')::uuid, 'SL', '2026-11-16', '2026-11-17', 'none', 'Fever', 'MC-20261116-0042');
  perform public._decide_leave((emp->>'E006')::uuid, (r->>'id')::uuid, 'approve', null);

  -- Priya (July 2026 joiner, AL pro-rated to 7): 4 days approved -> 3 / 7
  r := public._submit_leave((emp->>'E011')::uuid, 'AL', '2026-12-28', '2026-12-31', 'none', 'Trip home to Kochi', null);
  perform public._decide_leave((emp->>'E010')::uuid, (r->>'id')::uuid, 'approve', null);

  -- Siti: pending AL that clashes with Daniel (Team clash flag) -> in Marcus's inbox
  perform public._submit_leave((emp->>'E009')::uuid, 'AL', '2026-12-22', '2026-12-23', 'none', 'Wedding preparation', null);

  -- Marcus (Head of Operations): own leave routes to the Managing Director
  perform public._submit_leave((emp->>'E006')::uuid, 'AL', '2027-01-04', '2027-01-08', 'none', 'Annual holiday', null);

  -- Wei Jie: short-notice half day -> Sarah's inbox
  perform public._submit_leave((emp->>'E012')::uuid, 'AL', '2026-11-25', '2026-11-25', 'pm', 'Personal errand', null);

  -- Mei Ling: rejected request (shows remark on rejection)
  r := public._submit_leave((emp->>'E005')::uuid, 'AL', '2026-12-01', '2026-12-04', 'none', 'Short getaway', null);
  perform public._decide_leave((emp->>'E004')::uuid, (r->>'id')::uuid, 'reject', 'Month-end close runs 1–4 Dec. Could you take 7–10 Dec instead?');

  -- Daniel: 3-line claim SGD 140.30 -> approved -> paid in November payroll
  r := public._submit_claim((emp->>'E007')::uuid, 'Client site visit – Jurong (Nov)', jsonb_build_array(
    jsonb_build_object('expense_date', '2026-11-03', 'claim_type', 'TRANSPORT', 'description', 'Taxi to client site, Jurong',  'amount', 28.50, 'receipt_no', 'GRB-88123'),
    jsonb_build_object('expense_date', '2026-11-03', 'claim_type', 'MEALS',     'description', 'Working lunch with client (3 pax)', 'amount', 86.80, 'receipt_no', 'INV-55120'),
    jsonb_build_object('expense_date', '2026-11-03', 'claim_type', 'PARKING',   'description', 'Parking at client premises',  'amount', 25.00, 'receipt_no', 'PK-7781')
  ), true);
  perform public._decide_claim((emp->>'E006')::uuid, (r->>'id')::uuid, 'approve', null);
  perform public._finance_pay_claim((emp->>'E005')::uuid, (r->>'id')::uuid, 'PAYROLL-2026-11', '2026-11-20');

  -- Siti: approved claim waiting for Finance
  r := public._submit_claim((emp->>'E009')::uuid, 'Warehouse supplies', jsonb_build_array(
    jsonb_build_object('expense_date', '2026-11-12', 'claim_type', 'OFFICE', 'description', 'Labels and packing tape', 'amount', 42.60, 'receipt_no', 'POP-20931')
  ), true);
  perform public._decide_claim((emp->>'E006')::uuid, (r->>'id')::uuid, 'approve', 'OK');

  -- Priya: pending claim with an over-limit line -> Sarah's inbox
  perform public._submit_claim((emp->>'E011')::uuid, 'Client dinner – Q4 renewal', jsonb_build_array(
    jsonb_build_object('expense_date', '2026-11-18', 'claim_type', 'MEALS',     'description', 'Dinner with Acme procurement team (4 pax)', 'amount', 168.40, 'receipt_no', 'RST-30417'),
    jsonb_build_object('expense_date', '2026-11-18', 'claim_type', 'TRANSPORT', 'description', 'Taxi back from dinner', 'amount', 19.20, 'receipt_no', 'CDG-44102')
  ), true);
end $$;

-- Back-date the completed samples so the KPIs look like real history
update public.leave_requests set submitted_at = now() - interval '8 days', decided_at = now() - interval '7 days 20 hours'
  where status in ('approved', 'rejected');
update public.claims set submitted_at = now() - interval '14 days', decided_at = now() - interval '13 days', finance_at = now() - interval '1 hour'
  where status = 'paid';
update public.claims set submitted_at = now() - interval '6 days', decided_at = now() - interval '5 days'
  where status = 'submitted_to_finance';
